'use strict';
(() => {
 const M=VoyzBudget,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=v=>v===null||v===undefined?'—':new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(v);
 const groups=['Жильё','Транспорт','Кони','Активности','Входы и пропуска','Питание команды','Другое'];
 let account=null,client=VoyzCloud.init(),projects=[],choices={},projectFilter=new URLSearchParams(location.search).get('project')||'all',starting=null,authGeneration=0,busy=false,showTrash=false;
 const store=new VoyzBudgetStore({validate:M.validate,storage:localStorage,write:async(id,expected,document)=>{const {data,error}=await client.rpc('voyz_save_budget',{p_id:id,p_expected:expected,p_document:document});if(error)throw error;return data;},onChange:()=>{if(!busy)renderLight();}});
 const current=()=>store.active?.document,project=b=>projects.find(p=>p.id===b?.projectId),income=b=>M.crmIncome(project(b)?.document);
 const info=t=>$('#notice').textContent=t||'';
 const options=(items,value)=>items.map(([k,v])=>`<option value="${esc(k)}" ${k===value?'selected':''}>${esc(v)}</option>`).join('');
 const numeric=(field,value,label,scope='settings',id='',extra='')=>`<label><span>${esc(label)}</span><input type="number" min="0" step="any" data-scope="${scope}" data-id="${id}" data-field="${field}" aria-label="${esc(label)}" value="${esc(value)}" ${extra}></label>`;
 function currencies(value){const b=current();return options([...new Set([b.settings.currency,...Object.keys(b.settings.rates),value])].map(c=>[c,c]),value);}
 function projectOptions(value,all=false){return options([...(all?[['all','Все поездки']]:[]),...projects.map(p=>[p.id,p.document.tour.title]),['unassigned','Без привязки к поездке']],value);}
 function menu(){
 const b=current();$('#project').innerHTML=projectOptions(projectFilter,true);
 const search=$('#search').value.toLowerCase(),all=store.documents().filter(d=>projectFilter==='all'||d.projectId===projectFilter);
 $('#trash').textContent=showTrash?'← К сметам':'Удалённые ('+all.filter(d=>d.deletedAt).length+')';
 $('#budgets').innerHTML=all.filter(d=>!!d.deletedAt===showTrash&&d.title.toLowerCase().includes(search)).map(d=>{const r=store.records.get(d.id);return `<button class="variant" data-select="${d.id}" aria-current="${b?.id===d.id}"><strong>${!d.deletedAt&&choices[d.projectId]===d.id?'✓ ':''}${esc(d.title)}</strong><small>${d.settings.guests} гостей · ${d.settings.guides} гида · ${d.settings.currency}${r.dirty?' · есть правки':''}${d.deletedAt?' · удалена':d.settings.stage==='archived'?' · архив':''}</small></button>`;}).join('')||`<p class="hint">${showTrash?'Корзина пуста.':'Здесь пока нет смет. Нажмите ＋.'}</p>`;
}
 function renderLight(){menu();const b=current(),r=store.active;$('#editor').hidden=!b;$('#empty').hidden=!!b;$('#editor').classList.toggle('is-deleted',!!b?.deletedAt);$('#restore-budget').hidden=!b?.deletedAt;$('#delete-budget').hidden=!b||!!b.deletedAt;$('#title').disabled=!!b?.deletedAt;if(!b){$('#save-status').textContent=account?'Выберите или создайте смету':'Войдите, чтобы загрузить ваши сметы';return;}$('#save-status').textContent=r.pending?'Сохраняем онлайн…':r.error?'Не сохранено: '+r.error:r.dirty?'Есть правки · '+(account?'отправляем онлайн':'черновик на устройстве'):'Сохранено онлайн'+(r.savedAt?' · '+new Date(r.savedAt).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}):'');$('#primary').checked=choices[b.projectId]===b.id;$('#save').disabled=!!r.pending;totals();}
 function totals(){const b=current();if(!b)return;const c=M.compute(b,income(b)),base=b.settings.currency;const metric=(title,value,hint)=>`<div class="metric"><span>${title}</span><strong>${fmt(value)}</strong><small>${hint}</small></div>`;$('#totals').innerHTML=metric(c.unknown?'План · известная часть':'План расходов',c.plan,base+' · вся группа')+metric('На одного гостя',c.perGuest,base+' · '+b.settings.guests+' плательщиков')+metric('Уже потрачено',c.actual,base)+metric('Ещё потребуется',c.remaining,base+(c.forecastUnknown?' · неполный прогноз':''))+metric('Выручка',c.revenue,base+(b.settings.incomeSource==='crm'?' · из CRM':' · по цене варианта'))+metric('Получено / на руках',c.received,base+' · на руках '+fmt(c.cash))+metric('Прогноз расходов',c.forecast,base+(c.forecastUnknown?' · неполный':''))+metric('Прибыль по прогнозу',c.profitForecast,base);
  $('#missing').textContent=c.unknown?'Не заполнено: '+c.rows.filter(r=>r.plan===null).map(r=>r.name).join(', ')+'. Неполный бюджет не считается нулевым.':'План заполнен. Факт вносится по мере расходов; завершённые статьи отмечайте закрытыми.';
  const byId=new Map(c.rows.map(r=>[r.id,r]));document.querySelectorAll('[data-plan]').forEach(el=>el.textContent=fmt(byId.get(el.dataset.plan)?.plan??(b.lines.find(r=>r.id===el.dataset.plan)?.inactive?0:null)));document.querySelectorAll('[data-quantity]').forEach(el=>el.textContent='Количество: '+fmt(byId.get(el.dataset.quantity)?.quantity??(b.lines.find(r=>r.id===el.dataset.quantity)?.inactive?0:null)));
  for(const g of groups){const rows=c.rows.filter(r=>(r.category==='Авто'?'Транспорт':M.category(r))===g);const el=document.querySelector(`[data-subtotal="${g}"]`);if(el)el.textContent='План '+fmt(rows.reduce((n,r)=>n+(r.plan??0),0))+' · факт '+fmt(rows.reduce((n,r)=>n+(r.actual??0),0))+' '+base;}
  for(const v of b.vehicles){const rent=byId.get(v.id+'-rent'),fuel=byId.get(v.id+'-fuel'),el=document.querySelector(`[data-car-cost="${v.id}"]`);if(el)el.textContent='Аренда '+fmt(rent?.plan??(v.inactive?0:null))+' '+base+' · бензин '+fmt(fuel?.quantity??(v.inactive?0:null))+' л / '+fmt(fuel?.plan??(v.inactive?0:null))+' '+base;}
 }
 function settings(){const b=current(),s=b.settings;$('#settings').innerHTML=[['guests',s.guests,'Гостей'],['guides',s.guides,'Гидов'],['days',s.days,'Дней'],['nights',s.nights,'Ночей'],['salePrice',s.salePrice,'Цена / гость · '+s.currency]].map(([f,v,l])=>numeric(f,v,l)).join('');$('#received').value=s.received??'';$('#received').disabled=s.incomeSource==='crm';$('#base-currency').value=s.currency;$('#income-source').value=s.incomeSource||'manual';$('#stage').value=s.stage;$('#auto-cars').checked=s.autoCars;$('#assign-project').innerHTML=projectOptions(b.projectId);$('#rates').innerHTML=Object.entries(s.rates).filter(([c])=>c!==s.currency).map(([code,v])=>numeric(code,v,'1 '+code+' в '+s.currency,'rates')).join('');const p=project(b),crm=income(b);$('#route-link').href='index.html'+(p?'?tour='+encodeURIComponent(p.id):'');$('#crm-link').href='index.html'+(p?'?tour='+encodeURIComponent(p.id)+'&view=crm':'?view=crm');$('#crm-summary').textContent=crm?'В CRM: '+crm.guests+' участников · стоимость '+fmt(crm.revenue)+' · оплачено '+fmt(crm.received)+' '+crm.currency+'. Количество гостей в сценарии меняется независимо.':'Для CRM привяжите смету к поездке. Без участников выручка CRM равна 0.';}
 function lineHTML(r){return `<div class="expense-row" data-row="${r.id}">${r.inactive?'<p class="inactive-note">Исключено из плана. Введённый факт остаётся в расходах.</p>':''}<div class="expense-grid"><input class="name-input" data-scope="lines" data-id="${r.id}" data-field="name" aria-label="Название расхода" value="${esc(r.name)}" maxlength="500"><label class="cell-label"><span>Кто участвует</span><select data-scope="lines" data-id="${r.id}" data-field="basis" aria-label="Кто участвует">${options([['guests','Гости'],['all','Все + гиды'],['guides','Гиды'],['fixed','Вручную']],r.basis)}</select></label><label class="cell-label"><span>Единиц</span><input type="number" min="0" step="any" data-scope="lines" data-id="${r.id}" data-field="units" aria-label="Единиц" title="Единиц" value="${esc(r.unitsMode==='days'?current().settings.days:r.unitsMode==='nights'?current().settings.nights:r.units)}" ${r.unitsMode!=='fixed'?'disabled':''}></label><label class="cell-label"><span>Цена</span><input type="number" min="0" step="any" data-scope="lines" data-id="${r.id}" data-field="price" aria-label="Цена за единицу" title="Цена за единицу" value="${esc(r.price)}"></label><div class="value" data-plan="${r.id}"></div><label class="cell-label"><span>Факт</span><input type="number" min="0" step="any" data-scope="lines" data-id="${r.id}" data-field="actual" aria-label="Факт расхода" title="Факт в валюте учёта" placeholder="Факт" value="${esc(r.actual)}"></label>${r.inactive?`<button data-restore-line="${r.id}" aria-label="Вернуть расход" title="Вернуть в план">↶</button>`:`<button class="remove" data-remove-line="${r.id}" aria-label="Убрать расход">×</button>`}</div><div class="row-bottom"><span class="muted" data-quantity="${r.id}"></span><span class="muted">Цена в ${esc(r.currency)}${r.extra?' · +'+r.extra+' по той же цене':''}</span><label class="check"><input type="checkbox" data-scope="lines" data-id="${r.id}" data-field="closed" ${r.closed?'checked':''}> Расход закрыт</label></div><details class="row-details"><summary>Дополнительно: ${r.extra?'добавочный конь / участник, ':''}валюта, заметка</summary><div class="row-more">${numeric('extra',r.extra||0,'Добавить по той же цене','lines',r.id)}<label>Валюта цены<select data-scope="lines" data-id="${r.id}" data-field="currency">${currencies(r.currency)}</select></label><label>Единицы<select data-scope="lines" data-id="${r.id}" data-field="unitsMode">${options([['fixed','Задать вручную'],['days','По дням тура'],['nights','По ночам тура']],r.unitsMode)}</select></label><label>Раздел<select data-scope="lines" data-id="${r.id}" data-field="category">${options(groups.map(g=>[g,g]),M.category(r))}</select></label><textarea data-scope="lines" data-id="${r.id}" data-field="note" aria-label="Заметка расхода" maxlength="5000">${esc(r.note)}</textarea></div></details></div>`;}
 function carHTML(v){return `<div class="car" data-car="${v.id}">${v.inactive?'<p class="inactive-note">Машина исключена из плана. Введённый факт остаётся в расходах.</p>':''}<div class="car-top"><input data-scope="vehicles" data-id="${v.id}" data-field="name" aria-label="Название машины" value="${esc(v.name)}"><button data-copy-car="${v.id}">＋ Такая же</button>${v.inactive?`<button data-restore-car="${v.id}" aria-label="Вернуть машину">↶ Вернуть</button>`:`<button class="remove" data-remove-car="${v.id}" aria-label="Убрать машину">×</button>`}</div><div class="car-fields">${[['count',v.count,'Количество авто'],['days',v.days,'Суток аренды'],['rent',v.rent,'Аренда / сутки'],['km',v.km,'Пробег / авто, км'],['consumption',v.consumption,'Расход, л / 100 км'],['fuelPrice',v.fuelPrice,'Топливо / литр']].map(([f,val,l])=>numeric(f,val,l,'vehicles',v.id)).join('')}<label>Валюта аренды<select data-scope="vehicles" data-id="${v.id}" data-field="currency">${currencies(v.currency)}</select></label><label>Валюта топлива<select data-scope="vehicles" data-id="${v.id}" data-field="fuelCurrency">${currencies(v.fuelCurrency)}</select></label></div><div class="car-fact"><div><label>Факт аренды<input type="number" min="0" step="any" data-scope="vehicles" data-id="${v.id}" data-field="actualRent" aria-label="Факт аренды" value="${esc(v.actualRent)}"></label><label class="check"><input type="checkbox" data-scope="vehicles" data-id="${v.id}" data-field="rentClosed" ${v.rentClosed?'checked':''}> Закрыта</label></div><div><label>Факт топлива<input type="number" min="0" step="any" data-scope="vehicles" data-id="${v.id}" data-field="actualFuel" aria-label="Факт топлива" value="${esc(v.actualFuel)}"></label><label class="check"><input type="checkbox" data-scope="vehicles" data-id="${v.id}" data-field="fuelClosed" ${v.fuelClosed?'checked':''}> Закрыт</label></div></div><p class="car-cost" data-car-cost="${v.id}"></p></div>`;}
 function expenses(){
 const b=current(),labels='<div class="expense-labels"><span>Название</span><span>Кто</span><span>Единиц</span><span>Цена</span><span>План</span><span>Факт</span></div>';
 $('#expenses').innerHTML=groups.map(g=>{const all=b.lines.filter(r=>M.category(r)===g),rows=all.filter(r=>!r.inactive),parked=all.filter(r=>r.inactive),cars=g==='Транспорт'?b.vehicles:[],inactiveCars=cars.filter(v=>v.inactive),n=parked.length+inactiveCars.length;
 return `<section class="expense-group"><div class="group-head"><h2>${g}</h2><span class="subtotal" data-subtotal="${g}"></span><button data-add="${g}">＋ ${g==='Жильё'?'Ночь':g==='Транспорт'?'Машина':'Расход'}</button></div>${cars.filter(v=>!v.inactive).map(carHTML).join('')}${rows.length?labels+rows.map(lineHTML).join(''):g!=='Транспорт'?'<p class="hint" style="padding:0 12px">Пока нет расходов</p>':''}${g==='Транспорт'?'<button data-add-transfer style="margin:0 12px 12px">＋ Заброска / трансфер</button>':''}${n?`<details class="inactive-items"><summary>Не включены в план: ${n} · данные сохранены</summary>${inactiveCars.map(carHTML).join('')}${parked.length?labels+parked.map(lineHTML).join(''):''}</details>`:''}</section>`;
 }).join('');totals();
}
 function render(){if(current()?.deletedAt)showTrash=true;busy=true;menu();const b=current();$('#editor').hidden=!b;$('#empty').hidden=!!b;if(b){$('#title').value=b.title;$('#notes').value=b.notes;settings();expenses();}busy=false;renderLight();}
 function edit(fn){try{store.edit(fn);}catch(e){info(e.message);return false;}return true;}
 function askName(heading,initial){$('#name-heading').textContent=heading;$('#name-input').value=initial;$('#name-dialog').showModal();$('#name-input').focus();return new Promise(resolve=>{$('#name-form').onsubmit=e=>{e.preventDefault();const name=$('#name-input').value.trim();if(!name)return;$('#name-dialog').close();resolve(name);};$('#name-dialog').addEventListener('close',()=>resolve(null),{once:true});});}
 function confirm(title,text){$('#confirm-heading').textContent=title;$('#confirm-text').textContent=text;const d=$('#confirm-dialog');d.showModal();return new Promise(r=>d.addEventListener('close',()=>r(d.returnValue==='ok'),{once:true}));}
 function address(){const url=new URL(location.href);url.search='';if(current())url.searchParams.set('budget',current().id);url.hash='';history.replaceState(null,'',url);}
 async function newBudget(copy=false){if(!account){$('#login').showModal();return;}const source=current(),name=await askName(copy?'Копия сметы':'Новая смета',copy?source.title+' · копия':'Новая смета');if(!name)return;const doc=copy?M.duplicate(source,name):M.blank(name,projectFilter==='all'?(source?.projectId||'unassigned'):projectFilter);showTrash=false;store.add(doc);address();render();info('');await store.flush(doc.id);}
 async function refresh(){if(!account)return;const owner=account;const rows=[];for(let from=0;;from+=100){const {data,error}=await client.from('voyz_budgets').select('id,document,revision,updated_at').eq('owner_id',owner).order('id').range(from,from+99);if(error)throw error;rows.push(...data);if(data.length<100)break;}const {data:pick,error}=await client.from('voyz_budget_choices').select('project_id,budget_id').eq('owner_id',owner);if(error)throw error;const metadata=(await VoyzCloud.list()).filter(p=>!p.deletedAt),routes=await Promise.all(metadata.map(p=>VoyzCloud.get(p.id)));if(owner!==account)return;projects=routes.filter(Boolean);choices=Object.fromEntries(pick.map(x=>[x.project_id,x.budget_id]));return rows;}
 async function choose(on){const b=current();if(!await store.flush(b.id)){info('Сначала сохраните эту смету онлайн.');renderLight();return;}const {error}=await client.rpc('voyz_choose_budget',{p_project_id:b.projectId,p_budget_id:on?b.id:null});if(error){info(error.message);renderLight();return;}if(on)choices[b.projectId]=b.id;else delete choices[b.projectId];renderLight();}
 function addExpense(category){
 if(!current()||current().deletedAt)return;
 edit(d=>{if(category==='Жильё')M.resize(d,'nights',d.lines.filter(r=>r.night&&!r.inactive).length+1);
 else if(category==='Транспорт'){M.resize(d,'cars',d.vehicles.filter(v=>!v.inactive).length+1);d.settings.autoCars=false;}
 else d.lines.push({id:M.uid(),name:'Новый расход',category,basis:'fixed',units:1,unitsMode:'fixed',price:null,currency:d.settings.currency,actual:null,closed:false,extra:category==='Кони'?1:0,note:'',inactive:false});});expenses();settings();
}
 function isCountInput(el){return el.dataset.scope==='settings'&&['guests','guides','days','nights'].includes(el.dataset.field);}
 function handleFieldInput(e){const el=e.target,b=current();if(el.id==='search'){menu();return;}if(!b||b.deletedAt)return;if(el.id==='title'){edit(d=>d.title=el.value);return;}if(el.id==='notes'){edit(d=>d.notes=el.value);return;}const {scope,id,field}=el.dataset;if(!scope)return;const value=el.type==='checkbox'?el.checked:el.type==='number'?M.n(el.value):el.value;if(isCountInput(el)&&(value===null||!Number.isInteger(value))){el.value=b.settings[field];info('Введите целое количество. Данные сохранены.');return;}if(isCountInput(el)&&value===b.settings[field])return;if(value!==null&&el.type==='number'&&(!Number.isFinite(value)||value<0)){info('Введите неотрицательное число.');return;}
  const ok=edit(d=>{const row=scope==='settings'?d.settings:scope==='rates'?d.settings.rates:d[scope].find(r=>r.id===id);if(el.type==='checkbox'&&value){const f=field==='closed'?'actual':field==='rentClosed'?'actualRent':field==='fuelClosed'?'actualFuel':null;if(f&&row[f]===null)throw Error('Сначала внесите факт; если бесплатно — 0.');}if(isCountInput(el))M.setCount(d,field,value);else row[field]=value;if(scope==='lines'&&field==='category'){row.night=value==='Жильё';d.settings.nights=d.lines.filter(r=>r.night&&!r.inactive).length;}});
  if(!ok){if(el.type==='checkbox')el.checked=!value;if(isCountInput(el))el.value=b.settings[field];return;}info('');if((scope==='settings'&&['guides','days','nights'].includes(field))||['unitsMode','category'].includes(field))expenses();
 }
 document.addEventListener('input',e=>{if(!isCountInput(e.target))handleFieldInput(e);});
 document.addEventListener('change',e=>{if(isCountInput(e.target))handleFieldInput(e);});
 document.addEventListener('focusout',e=>{if(isCountInput(e.target))handleFieldInput(e);});
 document.addEventListener('keydown',e=>{if(isCountInput(e.target)&&e.key==='Enter'){e.preventDefault();e.target.blur();}});
 document.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el)return;try{if(el.dataset.close)$('#'+el.dataset.close).close();if(el.dataset.select){store.select(el.dataset.select);address();render();info('');}if(el.dataset.add)addExpense(el.dataset.add);if(el.hasAttribute('data-add-transfer')){edit(d=>{d.lines.push({id:M.uid(),name:'Заброска / трансфер',category:'Транспорт',basis:'fixed',units:1,unitsMode:'fixed',price:null,currency:d.settings.currency,actual:null,closed:false,extra:0,note:''});});expenses();}if(el.dataset.restoreLine||el.dataset.restoreCar){edit(d=>M.setInactive(d,el.dataset.restoreLine?'lines':'vehicles',el.dataset.restoreLine||el.dataset.restoreCar,false));settings();expenses();}if(el.dataset.copyCar){edit(d=>{const c=d.vehicles.find(v=>v.id===el.dataset.copyCar);d.vehicles.push({...structuredClone(c),id:M.uid(),name:c.name+' · копия',inactive:false,actualRent:null,actualFuel:null,rentClosed:false,fuelClosed:false});d.settings.autoCars=false;});settings();expenses();}if(el.dataset.removeLine||el.dataset.removeCar){if(!await confirm('Исключить из плана?','Название, цена, заметки и факт сохранятся. Вернуть строку можно в блоке «Не включены в план». Уже потраченные деньги останутся в расходах.'))return;edit(d=>M.setInactive(d,el.dataset.removeLine?'lines':'vehicles',el.dataset.removeLine||el.dataset.removeCar,true));settings();expenses();}}catch(e){info(e.message);}});
 $('#new').onclick=()=>newBudget();$('#empty-new').onclick=()=>newBudget();$('#copy').onclick=()=>newBudget(true);$('#save').onclick=async()=>{if(!account)return $('#login').showModal();await store.flushAll();};$('#primary').onchange=e=>choose(e.target.checked);
 $('#project').onchange=e=>{projectFilter=e.target.value;const docs=store.documents().filter(d=>(projectFilter==='all'||d.projectId===projectFilter)&&!!d.deletedAt===showTrash);if(docs.length)store.select(docs[0].id);else store.activeId=null;render();};$('#refresh').onclick=async()=>{try{if(!await store.flushAll())return info('Остались неотправленные правки. Сохраните копию при конфликте.');const rows=await refresh();store.refresh(rows);render();info('Данные обновлены с сервера.');}catch(e){info(e.message);}};
 $('#assign-project').onchange=async e=>{const b=current();if(choices[b.projectId]===b.id){e.target.value=b.projectId;return info('Сначала снимите отметку основной сметы.');}if(edit(d=>d.projectId=e.target.value)){projectFilter='all';render();}};
 $('#new-project').onclick=async()=>{if(!account)return $('#login').showModal();const name=await askName('Новая поездка','Новая поездка');if(!name)return;try{const id='v'+M.uid(),doc={kind:'voyz-tour',version:2,id,tour:{title:name,startDate:'',endDate:''},days:[],connections:[],view:{zoom:1},crm:{price:0,currency:'KGS',clients:[]}};const saved=await VoyzCloud.put(id,0,doc);projects.push({id,document:doc,revision:saved.revision});projectFilter=id;store.activeId=null;render();}catch(e){info(e.message);}};
 $('#income-source').onchange=e=>{edit(d=>d.settings.incomeSource=e.target.value);settings();};$('#received').oninput=e=>edit(d=>d.settings.received=M.n(e.target.value));$('#stage').onchange=e=>edit(d=>d.settings.stage=e.target.value);$('#auto-cars').onchange=e=>{if(edit(d=>{if(e.target.checked)M.resize(d,'cars',d.settings.guides);d.settings.autoCars=e.target.checked;}))expenses();};
 $('#base-currency').onchange=e=>{const code=e.target.value.toUpperCase(),b=current();if(!/^[A-Z]{3}$/.test(code)||b.lines.some(r=>r.actual!==null)||b.vehicles.some(r=>r.actualRent!==null||r.actualFuel!==null)||(b.settings.received||0)>0)return info('Валюту учёта меняют до внесения факта и оплат.');edit(d=>{const old=d.settings.currency;d.settings.currency=code;d.settings.rates=Object.fromEntries([...new Set([old,...Object.keys(d.settings.rates)])].filter(c=>c!==code).map(c=>[c,null]));});render();info('Введите курсы для новой валюты. Цены расходов сохранены в исходных валютах.');};
 $('#add-currency').onclick=()=>{const code=$('#currency-code').value.toUpperCase();if(!/^[A-Z]{3}$/.test(code))return info('Код валюты — три латинские буквы.');edit(d=>{if(code!==d.settings.currency&&!Object.hasOwn(d.settings.rates,code))d.settings.rates[code]=null;});settings();expenses();};
 $('#crm-count').onclick=()=>{const i=income(current());if(!i||!i.guests)return info('В CRM пока нет участников.');edit(d=>d.settings.guests=i.guests);settings();expenses();};
 $('#apply-price').onclick=async()=>{const b=current(),p=project(b);if(!p||b.settings.salePrice===null)return info('Выберите поездку и задайте цену за гостя.');const fresh=await VoyzCloud.get(p.id),crm=fresh.document.crm;if(crm.currency!==b.settings.currency)return info('Валюты CRM и сметы различаются. Сначала согласуйте валюту.');if(!await confirm('Применить цену к участникам?','Обновится стандартная цена и участники со старой стандартной ценой. Индивидуальные цены, предоплаты и доплаты сохранятся.'))return;const old=crm.price;crm.price=b.settings.salePrice;crm.clients.forEach(c=>{if(c.price===old||c.price===0)c.price=crm.price;});try{const result=await VoyzCloud.put(p.id,fresh.revision,fresh.document);Object.assign(p,{document:fresh.document,revision:result.revision});render();info('Цена применена. Оплаты сохранены.');}catch(e){info(e.message);}};
 $('#link').onclick=async()=>{if(!await store.flush())return info('Сначала сохраните смету онлайн.');const url=new URL('budget.html',location.href);url.searchParams.set('budget',current().id);try{await navigator.clipboard.writeText(url.href);info('Ссылка скопирована. На другом устройстве войдите той же почтой.');}catch{info(url.href);}};
 function download(data,name,type){const url=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),15000);}
 function excel(all=false){const docs=all?store.documents().filter(d=>!d.deletedAt):[current()],rows=all?[['Поездка','Смета','Основная','Гостей','Валюта','План','Факт','Выручка','Получено','Прогноз прибыли'],...docs.map(b=>{const c=M.compute(b,income(b));return [project(b)?.document.tour.title||'Без привязки',b.title,choices[b.projectId]===b.id?'Да':'Нет',b.settings.guests,b.settings.currency,c.plan,c.actual,c.revenue,c.received,c.profitForecast];})]:[['VOYZ · '+current().title,'Валюта: '+current().settings.currency],['Источник: введённые данные, снимок '+new Date().toLocaleString('ru-RU')],['Раздел','Расход','Количество','План','Факт','Прогноз','Валюта исходной суммы','Исходная сумма'],...M.compute(current(),income(current())).rows.map(r=>[r.category,r.name,r.quantity,r.plan,r.actual,r.forecast,r.currency,r.native]),[],['Примечания',current().notes]];download(VoyzBudgetXlsx([{name:all?'Все варианты':'Смета',rows}]),all?'VOYZ-все-сметы.xlsx':'VOYZ-смета.xlsx');}
 $('#excel').onclick=()=>excel();$('#excel-all').onclick=()=>excel(true);$('#backup').onclick=()=>download(JSON.stringify({kind:'voyz-budgets',version:2,documents:store.documents()},null,2),'VOYZ-сметы-бэкап.json','application/json');$('#import').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{try{const raw=JSON.parse((await e.target.files[0].text()).replace(/^\uFEFF/,'')),docs=raw.kind==='voyz-budgets'?raw.documents:[raw];for(const doc of docs)store.add(M.duplicate(M.validate(doc)));render();await store.flushAll();}catch(e){info(e.message);}};
 $('#history').onclick=async()=>{if(!account)return;$('#history-dialog').showModal();$('#versions').textContent='Загружаем…';const {data,error}=await client.from('voyz_budget_versions').select('revision,document,saved_at').eq('owner_id',account).eq('budget_id',current().id).order('revision',{ascending:false}).limit(50);if(error)return $('#versions').textContent=error.message;$('#versions').replaceChildren();for(const v of data){const button=document.createElement('button');button.textContent='Версия '+v.revision+' · '+new Date(v.saved_at).toLocaleString('ru-RU');button.onclick=async()=>{store.add(M.duplicate(M.validate(v.document),v.document.title+' · версия '+v.revision));render();address();$('#history-dialog').close();await store.flush();};$('#versions').append(button);}};
 $('#portfolio-open').onclick=()=>{const incomes=Object.fromEntries(projects.map(p=>[p.id,M.crmIncome(p.document)])),p=M.portfolio(store.documents(),choices,incomes);$('#portfolio').innerHTML=Object.entries(p).map(([code,x])=>`<h3>${esc(code)} · ${x.count} основных смет</h3><p>Выручка: ${fmt(x.revenue)} · Получено: ${fmt(x.received)}<br>План: ${fmt(x.knownPlan)} · расходы по факту: ${fmt(x.actual)} · Прогноз прибыли: ${x.incomplete?'— (не все сметы заполнены)':fmt(x.forecastProfit)}<br>Прибыль закрытых поездок: ${fmt(x.completedProfit)} (${x.completed} поездок)${x.incomplete?'<br>Неполных расчётов: '+x.incomplete:''}</p>`).join('')||'<p>Поставьте отметку «Основная смета поездки» у нужных вариантов. Остальные расчёты не входят в общий итог.</p>';$('#portfolio-dialog').showModal();};
 $('#auth').onclick=async()=>{if(!account)return $('#login').showModal();if(!await store.flushAll())return info('Сначала сохраните правки или выгрузите резервную копию.');await VoyzCloud.signOut();};$('#login-form').onsubmit=async e=>{e.preventDefault();try{await client.auth.signInWithOtp({email:$('#email').value,options:{shouldCreateUser:false,emailRedirectTo:VoyzCloud.configured()?window.VOYZ_CLOUD.publicUrl:location.href}}).then(({error})=>{if(error)throw error;});$('#login-status').textContent='Письмо отправлено. Откройте ссылку на нужном устройстве.';}catch(e){$('#login-status').textContent=e.message;}};
 async function auth(next){const id=next?.user?.id||null;if(id===account&&starting)return starting;if(id===account&&store.owner)return;const generation=++authGeneration;account=id;$('#account').textContent=next?.user?.email||'Без входа';$('#auth').textContent=id?'Выйти':'Войти';starting=(async()=>{try{if(!id){projects=[];choices={};store.open('guest',[],null);render();info('Войдите по почте, чтобы увидеть все поездки и сметы.');return;}const rows=await refresh();if(generation!==authGeneration)return;const requested=new URLSearchParams(location.search).get('budget');store.open(id,rows,requested);if(!requested&&projectFilter!=='all'){const match=store.documents().find(d=>d.projectId===projectFilter&&!d.deletedAt);store.activeId=match?.id||null;}const legacy=JSON.parse(localStorage.getItem('voyz-budget-draft.v1.'+id)||'null');if(legacy?.dirty){try{const old=M.validate(legacy.document),online=store.records.get(old.id);if(!online)store.add(old);else if(JSON.stringify(old)!==JSON.stringify(online.document)){const recovered=M.duplicate(old,old.title+' · восстановленный черновик');store.add(recovered);}localStorage.removeItem('voyz-budget-draft.v1.'+id);}catch{}}render();info('');}catch(e){if(generation!==authGeneration)return;if(store.owner!==id)store.open(id,[],new URLSearchParams(location.search).get('budget'),true);render();info('Нет доступа к серверу: '+e.message+'. Открыта аварийная копия этого устройства. Онлайн-сохранение будет проверено после подключения.');}})();return starting;}
 window.addEventListener('online',()=>store.flushAll());window.addEventListener('focus',async()=>{if(!account||document.querySelector('dialog[open]')||/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName))return;try{const rows=await refresh();store.refresh(rows);render();}catch(e){info('Не удалось получить обновления: '+e.message);}});window.addEventListener('beforeunload',e=>{store.persist();if([...store.records.values()].some(r=>r.dirty||r.pending)){e.preventDefault();e.returnValue='';}});
 
 $('#trash').onclick=()=>{showTrash=!showTrash;const next=store.documents().find(d=>(projectFilter==='all'||d.projectId===projectFilter)&&!!d.deletedAt===showTrash);store.activeId=next?.id||null;address();render();info('');};
 $('#delete-budget').onclick=async()=>{const b=current();if(!b||b.deletedAt)return;const id=b.id;if(!await confirm('Удалить вариант сметы?',`«${b.title}» будет перемещена в корзину. Все данные сохранятся; восстановить вариант можно через «Удалённые». В общих итогах он учитываться не будет.`))return;
 if(!await store.flush(id))return info('Не удалось сохранить последние правки. Смета не удалена.');
 try{const {error}=await client.from('voyz_budget_choices').delete().eq('owner_id',account).eq('budget_id',id);if(error)throw error;if(choices[b.projectId]===id)delete choices[b.projectId];store.edit(d=>d.deletedAt=new Date().toISOString(),id);if(!await store.flush(id)){showTrash=true;render();return;}
 const next=store.documents().find(d=>!d.deletedAt&&d.id!==id&&(projectFilter==='all'||d.projectId===projectFilter));store.activeId=next?.id||null;showTrash=false;address();render();info('Смета в корзине. Вернуть её можно через «Удалённые».');}catch(e){info('Не удалось удалить: '+e.message);}};
 $('#restore-budget').onclick=async()=>{const id=current()?.id;if(!id)return;store.edit(d=>delete d.deletedAt,id);showTrash=false;render();await store.flush(id);info('Смета восстановлена. При необходимости отметьте её основной.');};

 VoyzCloud.onAuth(auth);VoyzCloud.session().then(auth).catch(e=>info(e.message));
})();
